import {RelativeTime, Spinner} from '@primer/react'

export function ScanStatusInTile({
  isComplete,
  pctComplete,
  requestedAt,
}: {
  isComplete: boolean
  pctComplete: number
  requestedAt: string
}) {
  if (isComplete) {
    return (
      <p className="f6 fgColor-muted d-flex flex-items-center gap-1 mt-1" data-testid="scan-status-in-tile">
        <span>
          Scan completed <RelativeTime datetime={requestedAt} />
        </span>
      </p>
    )
  }

  return (
    <p className="f6 fgColor-muted d-flex flex-items-center gap-1 mt-1" data-testid="scan-status-in-tile">
      <Spinner size="small" />
      <span>{pctComplete > 0 ? `Scan ${pctComplete}% complete` : 'Queued to start'}</span>
    </p>
  )
}
