import {useRef, useState} from 'react'
import type {EnablementSuccess} from '../types'

export function useEnablementState() {
  const [isEnablementDialogOpen, setIsEnablementDialogOpen] = useState(false)
  const [isROICalculatorOpen, setIsROICalculatorOpen] = useState(false)
  const [hideUpsellBanner, setHideUpsellBanner] = useState(false)
  const [enablementSuccess, setEnablementSuccess] = useState<EnablementSuccess>({
    showBanner: false,
    repoCount: 0,
    showSecurityDashboardButton: false,
  })

  const setCurrentModalRef = useRef<((modal: 'publicRepos' | 'allRepos' | null) => void) | null>(null)

  const handleEnablement = (payload: EnablementSuccess) => {
    setEnablementSuccess(payload)
    if (payload.showBanner) {
      setHideUpsellBanner(true)
    }
  }

  return {
    isEnablementDialogOpen,
    setIsEnablementDialogOpen,
    isROICalculatorOpen,
    setIsROICalculatorOpen,
    hideUpsellBanner,
    enablementSuccess,
    setEnablementSuccess,
    setCurrentModalRef,
    handleEnablement,
  }
}
