import type {ReactNode} from 'react'
import {Stack} from '@primer/react'

interface EnablementBannerProps {
  title: string
  description: ReactNode
  actions: ReactNode
  analyticsVisible?: Record<string, string>
  testId?: string
}

export function EnablementBanner({title, description, actions, analyticsVisible, testId}: EnablementBannerProps) {
  return (
    <div
      className="d-flex flex-justify-between flex-items-center tmp-p-3 bgColor-default border rounded-2"
      data-analytics-visible={analyticsVisible ? JSON.stringify(analyticsVisible) : undefined}
      data-testid={testId}
    >
      <div>
        <h2 className="h4 mb-1">{title}</h2>
        <p className="fgColor-muted f5 mb-0">{description}</p>
      </div>
      <Stack direction="horizontal" align="center" gap="condensed">
        {actions}
      </Stack>
    </div>
  )
}
