import {useState} from 'react'

import {Banner, Link} from '@primer/react'
import {useQuery} from '@github-ui/react-query'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {useClickAnalytics} from '@github-ui/use-analytics'

import {UpsellBanner} from '@github-ui/platform-patterns/UpsellBanner'

import {queries, useCreateAssessmentMutation} from '../api'
import {CodeSecurityAssessmentResultPage} from '../components/CodeSecurityResultPage'
import {RunAssessmentDialog} from '../components/shared/RunAssessmentDialog'
import codeScanningStartScanDay from '../assets/code-scanning-start_scan_banner--day.svg'
import codeScanningStartScanNight from '../assets/code-scanning-start_scan_banner--night.svg'
import type {CreateAssessmentParams, Org} from '../types'
import {DEFAULT_ELIGIBILITY, ASSESSMENT_SOURCE} from '../types'
import {ACTIONS_RUNNERS_DOCS_URL, SUPPORTED_LANGUAGES_URL, WATCH_A_DEMO_URL} from '../constants'
import {CodeSecurityFaq} from '../components/CodeSecurityResultPage/CodeSecurityFaq'

const SOURCE = ASSESSMENT_SOURCE.CODE_SECURITY

interface CodeSecurityRiskAssessmentPageProps {
  org: Org
  hasExistingAssessment?: boolean
}

export function CodeSecurityRiskAssessmentPage({org, hasExistingAssessment}: CodeSecurityRiskAssessmentPageProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const mutation = useCreateAssessmentMutation({org: org.login, source: SOURCE})
  const {data: eligibility, isLoading: isEligibilityLoading} = useQuery(queries.eligibility(org.login))
  // Show the runners-blocked state when eligibility indicates GitHub-hosted runners are blocked for CSRA.
  const runnersBlocked = eligibility?.csra?.github_hosted_runners_blocked === true
  const {
    data: eligibleReposData,
    isLoading: isReposLoading,
    isError: isReposError,
  } = useQuery({
    ...queries.codeSecurityEligibleRepos(org.login, undefined),
    enabled: !hasExistingAssessment,
  })
  const resolvedEligibility = eligibility ?? DEFAULT_ELIGIBILITY
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showSraCopilotAssist = useFeatureFlag('risk_assessment_copilot_assistive')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showCsraCopilotAssist = useFeatureFlag('csra_copilot_assistive')
  const showDemoLink = showSraCopilotAssist || showCsraCopilotAssist
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const isBusy = mutation.isPending || isEligibilityLoading || isReposLoading

  const handleStartScan = (params: CreateAssessmentParams) => {
    mutation.mutate(params)
  }

  if (hasExistingAssessment) {
    return <CodeSecurityAssessmentResultPage org={org} />
  }

  if (runnersBlocked) {
    return (
      <>
        <RunnersBlockedBanner />
        <CodeSecurityFaq />
      </>
    )
  }

  const hasNoEligibleRepos =
    !isReposLoading &&
    !isReposError &&
    eligibleReposData !== undefined &&
    eligibleReposData.totalEligibleRepoCount === 0

  if (hasNoEligibleRepos) {
    return (
      <>
        <NoEligibleReposBanner />
        <CodeSecurityFaq />
      </>
    )
  }

  return (
    <>
      {mutation.isError && (
        <Banner
          variant="critical"
          title="Error"
          description="Failed to scan your organization. Please try again later."
        />
      )}
      <UpsellBanner
        heading="Scan your organization for vulnerabilities"
        description="Scan your organization for free with code scanning and get an audit of vulnerabilities and their severity levels, rule types and language breakdown."
        primaryActionText="Scan organization"
        primaryActionOnClick={() => {
          if (!isBusy) setIsDialogOpen(true)
        }}
        secondaryActionText={showDemoLink ? 'Watch a demo' : 'Learn more'}
        secondaryActionOnClick={
          showDemoLink
            ? () => {
                sendClickAnalyticsEvent({
                  location: 'security-assessment-pre-scan',
                  category: 'code-security-banner',
                  action: 'watch-demo',
                  tag: 'link',
                  group: 'expand',
                })
              }
            : undefined
        }
        secondaryActionHref={showDemoLink ? WATCH_A_DEMO_URL : '#'}
        productShotLight={codeScanningStartScanDay}
        productShotDark={codeScanningStartScanNight}
      />
      <CodeSecurityFaq />
      {isDialogOpen && (
        <RunAssessmentDialog
          onClose={() => setIsDialogOpen(false)}
          onStartScan={handleStartScan}
          org={org}
          source={SOURCE}
          eligibility={resolvedEligibility}
        />
      )}
    </>
  )
}

function NoEligibleReposBanner() {
  return (
    <UpsellBanner
      heading="Nothing to scan yet"
      description={
        <>
          <Link inline href={SUPPORTED_LANGUAGES_URL}>
            Code scanning
          </Link>{' '}
          works with languages like JavaScript, Python, Java, C/C++, and more. Your organization doesn&apos;t currently
          have any private or internal repositories using supported languages, so there&apos;s nothing to scan right
          now.
        </>
      }
      primaryActionText="Learn more about supported languages"
      primaryActionHref={SUPPORTED_LANGUAGES_URL}
      productShotLight={codeScanningStartScanDay}
      productShotDark={codeScanningStartScanNight}
    />
  )
}

function RunnersBlockedBanner() {
  return (
    <UpsellBanner
      heading="GitHub-hosted runners are required"
      description={
        <>
          To run a Code Security Risk Assessment, your enterprise must allow GitHub-hosted runners.{' '}
          <Link inline href={SUPPORTED_LANGUAGES_URL}>
            Code scanning
          </Link>{' '}
          relies on them to analyze your repositories. Contact your enterprise administrator to update your policies.
        </>
      }
      secondaryActionText="Learn more about Actions runners"
      secondaryActionHref={ACTIONS_RUNNERS_DOCS_URL}
      productShotLight={codeScanningStartScanDay}
      productShotDark={codeScanningStartScanNight}
    />
  )
}
