import {useId, useState} from 'react'
import DataCard from '@github-ui/data-card'
import {InfoIcon, KeyIcon} from '@primer/octicons-react'
import {ActionList, Banner, Button, Link} from '@primer/react'
import {DataTable, Table, type Column} from '@primer/react/experimental'
import {toPercentInt} from '@github-ui/secret-scanning/utils'
import Pluralize from 'pluralize'
import type {Assessment, AssessmentSummary, Cost, Org, TokenTypeLocaleResult} from '../types'
import {ALL_REPOS_REPO_COUNT} from '../constants'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {EnablementDialog} from './shared/EnablementDialog'
import {ROICalculator} from './SecretProtectionResultPage/ROICalculator'
import {InfoButton} from './shared/InfoButton'
import {ScanStatusInTile} from './SecretProtectionResultPage/ScanStatusInTile'
import {CalculatorButtons} from './SecretProtectionResultPage/CalculatorButtons'
import {UpsellBanner} from './SecretProtectionResultPage/UpsellBanner'
import {NoLeaksBanner, NoLeaksSuccessBanner} from './SecretProtectionResultPage/NoLeaksBanner'
import {AssessmentResultBanner} from './SecretProtectionResultPage/AssessmentResultBanner'
import {StartTrialDialog} from './shared/StartTrialDialog'
import {useGhasTrial} from '../hooks/use-ghas-trial'
import {ContactAdministratorBanner} from './SecretProtectionResultPage/ContactAdministratorBanner'
import {ScanInProgressBanner} from './shared/ScanInProgressBanner'
import {ProgressCardItem} from './SecretProtectionResultPage/ProgressCardItem'
import {useEnablementState} from '../hooks/use-enablement-state'

export function AssessmentResultPage({
  assessment,
  assessmentList = null,
  cost,
  helpUrl,
  org,
  hawaiiExpVariant = 0,
  isEnterpriseOrMT,
  showEnableSecretProtectionButton = true,
  showEnableSecretProtectionBanner = true,
}: {
  assessment: Assessment
  assessmentList?: AssessmentSummary[] | null
  cost: Cost
  helpUrl: string
  org: Org
  hawaiiExpVariant?: number
  isEnterpriseOrMT?: boolean
  showEnableSecretProtectionButton?: boolean
  showEnableSecretProtectionBanner?: boolean
}) {
  const [pageIndex, setPageIndex] = useState(0)
  const {
    isEnablementDialogOpen,
    setIsEnablementDialogOpen,
    isROICalculatorOpen,
    setIsROICalculatorOpen,
    hideUpsellBanner,
    enablementSuccess,
    setEnablementSuccess,
    setCurrentModalRef,
    handleEnablement,
  } = useEnablementState()

  const [isStartTrialDialogOpen, setIsStartTrialDialogOpen] = useState(false)
  const {ghasTrial} = useGhasTrial()

  const dataTableId = useId()
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const pageSize = 15
  const dataCardClass = 'flex-basis-full md:flex-basis-auto'

  const assessmentDates = (assessmentList || []).map((assessmentSummary, index) => {
    const dateValue = assessmentSummary.requestedAt
    if (!dateValue) {
      return {id: `invalid-date${index}`, date: 'Unknown date', number: assessmentSummary.Number}
    }

    const date = new Date(dateValue)

    const formattedDate = date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      timeZone: 'UTC',
    })

    return {id: dateValue, date: formattedDate, number: assessmentSummary.Number}
  })

  const start = pageIndex * pageSize
  const end = start + pageSize
  const data: TokenTypeLocaleResult[] = assessment.tokens.slice(start, end).map(item => ({
    ...item,
    distinct_repos_count: item.distinct_repos_count.toLocaleString(),
    unique_tokens_found_count: item.unique_tokens_found_count.toLocaleString(),
  }))

  const columns: Array<Column<TokenTypeLocaleResult>> = [
    {
      header: 'Secret type',
      field: 'name',
    },
    {
      header: 'Distinct repositories',
      field: 'distinct_repos_count',
      align: 'end',
    },
    {
      header: 'Secrets found',
      field: 'unique_tokens_found_count' as const,
      align: 'end',
    },
  ]

  const showEnableAllBanner = showEnableSecretProtectionButton && showEnableSecretProtectionBanner

  const noLeaks = assessment.is_complete && assessment.total_tokens_found === 0

  const pctComplete = toPercentInt(assessment.total_scans_completed, assessment.total_scans_wanted, {
    floor: true,
  })
  const assessmentInQueuedState = pctComplete === 0 && !assessment.is_complete

  const enablementDialogAssessmentNumber = assessmentList?.[0]?.Number
  const enablementDialogAssessmentDate = assessmentDates[0]?.date
  const showEnablementDialog = org.is_ghas_metered && !!enablementDialogAssessmentNumber

  const calculatorButtons = showEnablementDialog ? (
    <CalculatorButtons
      setIsEnablementDialogOpen={setIsEnablementDialogOpen}
      setIsROICalculatorOpen={setIsROICalculatorOpen}
      sendClickAnalyticsEvent={sendClickAnalyticsEvent}
      buttonVariant="primary"
    />
  ) : null

  // Overflow menu items shown inside the post-assessment banner when the org is
  // eligible to start a GHAS trial. Mirrors the entry points exposed by
  // CalculatorButtons so users can still reach enablement / ROI flows.
  const trialOverflowMenuItems = showEnablementDialog ? (
    <>
      <ActionList.Item
        onSelect={() => {
          setIsEnablementDialogOpen(true)
          sendClickAnalyticsEvent({
            location: 'security-assessment-post-scan',
            category: 'results-banner',
            action: 'open-enablement-dialog',
            group: 'expand',
          })
        }}
      >
        Enable Secret Protection
      </ActionList.Item>
      <ActionList.Item
        onSelect={() => {
          setIsROICalculatorOpen(true)
          sendClickAnalyticsEvent({
            location: 'security-assessment-post-scan',
            category: 'results-banner',
            action: 'roi-calculator',
            group: 'expand',
          })
        }}
      >
        Estimate push protection savings
      </ActionList.Item>
    </>
  ) : null

  return (
    <div className="d-flex flex-column gap-3">
      {showEnablementDialog && (
        <EnablementDialog
          isOpen={isEnablementDialogOpen}
          onClose={() => setIsEnablementDialogOpen(false)}
          cost={cost}
          org={org}
          handleEnablement={handleEnablement}
          assessmentNumber={enablementDialogAssessmentNumber}
          assessmentDate={enablementDialogAssessmentDate}
          isEnterpriseOrMT={isEnterpriseOrMT}
          context="secret-protection"
        />
      )}

      <StartTrialDialog
        isOpen={isStartTrialDialogOpen}
        onClose={() => setIsStartTrialDialogOpen(false)}
        orgLogin={org.login}
        trialDays={ghasTrial?.trial_days}
      />

      <ROICalculator
        isOpen={isROICalculatorOpen}
        onClose={() => setIsROICalculatorOpen(false)}
        totalPreventableSecretsFound={assessment.total_tokens_found_push_protected_patterns}
        showEnablementDialog={showEnablementDialog}
        onEnableAllRepos={() => {
          if (setCurrentModalRef.current) {
            setCurrentModalRef.current('allRepos')
            sendClickAnalyticsEvent({
              location: 'security-assessment-post-scan',
              category: noLeaks ? 'no-secrets-banner' : 'protect-repos-banner',
              action: 'enable-for-all-repos',
              tag: 'button',
              group: 'expand',
            })
          }
        }}
        onOpenEnablementDialog={() => setIsEnablementDialogOpen(true)}
      />

      {noLeaks && showEnableAllBanner && (
        <UpsellBanner
          cost={cost}
          buttonVariant="primary"
          renderBanner={enableButtons => (
            <NoLeaksBanner
              enableButtons={calculatorButtons ?? enableButtons}
              trialOverflowMenuItems={trialOverflowMenuItems}
              onStartTrial={() => setIsStartTrialDialogOpen(true)}
            />
          )}
          successBanner={<NoLeaksSuccessBanner />}
          hawaiiExpVariant={hawaiiExpVariant}
          org={org.login}
          helpUrl={helpUrl}
          noLeaks={noLeaks}
          showPublicRepoOption={!isEnterpriseOrMT}
          showEnableSecretProtectionButton={showEnableSecretProtectionButton}
          setIsROICalculatorOpen={setIsROICalculatorOpen}
          setCurrentModalRef={setCurrentModalRef}
        />
      )}
      {!assessment.is_complete && (
        <ScanInProgressBanner
          analyticsLocation="security-assessment"
          analyticsVisible={{
            category: 'scan-in-progress-banner',
            action: 'visible',
            group: 'expand',
            location: 'security-assessment',
          }}
          icon={<InfoIcon />}
          description={
            <>
              Meanwhile,{' '}
              <Link inline href={`/resources/articles/security`}>
                explore resources
              </Link>{' '}
              like the{' '}
              <Link inline href={`/resources/whitepapers/secret-scanning-a-key-to-your-cybersecurity-strategy`}>
                secret leak expert guide
              </Link>
              .
            </>
          }
        />
      )}
      {assessment.is_complete && !showEnableSecretProtectionButton && <ContactAdministratorBanner />}
      {enablementSuccess.showBanner && (
        <Banner
          variant="success"
          title={`Secret protection enabled for ${
            enablementSuccess.repoCount === ALL_REPOS_REPO_COUNT
              ? 'all existing and future repositories'
              : `${enablementSuccess.repoCount} ${Pluralize('repository', enablementSuccess.repoCount, false)}`
          }`}
          description={
            <>
              <p>
                Manage features like bypass requests and custom patterns in{' '}
                <Link href={`/organizations/${org.login}/settings/security_products`} inline>
                  settings
                </Link>
                {'.'}
              </p>
              {enablementSuccess.showSecurityDashboardButton && (
                <Button as="a" href={`/orgs/${org.login}/security/overview`}>
                  View your security dashboard
                </Button>
              )}
            </>
          }
          onDismiss={() => setEnablementSuccess({repoCount: 0, showBanner: false, showSecurityDashboardButton: false})}
        />
      )}
      {assessment.is_complete && !noLeaks && showEnableAllBanner && !hideUpsellBanner && (
        <UpsellBanner
          cost={cost}
          hawaiiExpVariant={hawaiiExpVariant}
          renderBanner={enableButtons => (
            <AssessmentResultBanner
              enableButtons={calculatorButtons ?? enableButtons}
              trialOverflowMenuItems={trialOverflowMenuItems}
              onStartTrial={() => setIsStartTrialDialogOpen(true)}
            />
          )}
          successBanner={
            <Banner
              variant="success"
              icon={<KeyIcon />}
              title="Settings applied"
              data-analytics-visible='{"category":"protection-applied-banner","action":"visible","group":"expand","location":"security-assessment-post-scan"}'
              description={
                <>
                  <p>
                    GitHub Secret Protection is enabled for your organization. For very large organizations, this may
                    take some time to complete. As for now, treat yourself — you did good today. ✨
                  </p>
                </>
              }
            />
          }
          org={org.login}
          helpUrl={helpUrl}
          noLeaks={noLeaks}
          showPublicRepoOption={!isEnterpriseOrMT}
          showEnableSecretProtectionButton={showEnableSecretProtectionButton}
          setIsROICalculatorOpen={setIsROICalculatorOpen}
          setCurrentModalRef={setCurrentModalRef}
        />
      )}
      <div className="d-flex flex-justify-between flex-wrap md:flex-nowrap gap-3">
        <DataCard
          className={dataCardClass}
          cardTitle={
            <div className="d-flex flex-items-center gap-1">
              <span>Total secrets</span>
              <InfoButton
                ariaLabel="Total secrets info"
                title="Secret leaks found across your organization repositories."
              />
            </div>
          }
          loading={assessmentInQueuedState}
          data-testid="total-secrets-card"
        >
          <DataCard.Counter count={assessment.total_tokens_found} />
          <ScanStatusInTile
            isComplete={assessment.is_complete}
            pctComplete={pctComplete}
            requestedAt={assessment.requested_at}
          />
        </DataCard>
        <DataCard className={dataCardClass} cardTitle="Public leaks" loading={assessmentInQueuedState}>
          <DataCard.Counter count={assessment.total_tokens_found_in_public_repo} />
          <DataCard.Description>Distinct secrets found in your public repositories.</DataCard.Description>
        </DataCard>
        {!noLeaks ? (
          <DataCard className={dataCardClass} cardTitle="Preventable leaks" loading={assessmentInQueuedState}>
            <DataCard.Counter count={assessment.total_tokens_found_push_protected_patterns} />
            <DataCard.Description>
              Secrets which could have been prevented with{' '}
              <Link href={`${helpUrl}/code-security/secret-scanning/introduction/about-push-protection`} inline>
                push protection
              </Link>
              .
            </DataCard.Description>
          </DataCard>
        ) : (
          <>
            <DataCard className={dataCardClass} cardTitle="Repositories scanned" loading={assessmentInQueuedState}>
              <DataCard.Counter count={assessment.distinct_repos_scanned} />
              <DataCard.Description>Repositories scanned across your organization on GitHub.</DataCard.Description>
            </DataCard>
          </>
        )}
      </div>
      <div className="d-flex flex-justify-between flex-wrap md:flex-nowrap gap-3">
        {!noLeaks && (
          <>
            <DataCard className={dataCardClass} cardTitle="Secret locations" loading={assessmentInQueuedState}>
              <DataCard.ProgressBar data={[{progress: 100, label: 'Code'}]} />
              <div className="d-flex flex-wrap gap-2 mb-1">
                <ProgressCardItem
                  label="Code"
                  labelColor="fgColor-accent"
                  data={{
                    count: assessment.total_tokens_found,
                    total: assessment.total_tokens_found,
                  }}
                />
                <ProgressCardItem label="Issues" labelColor="fgColor-muted" />
                <ProgressCardItem label="Wikis" labelColor="fgColor-muted" />
                <ProgressCardItem label="Pull requests" labelColor="fgColor-muted" />
              </div>
              <p className="fgColor-muted f6">
                Continuously scan additional locations outside of git history with{' '}
                <Link href={`${helpUrl}/code-security/secret-scanning`} inline>
                  secret scanning
                </Link>
                .
              </p>
            </DataCard>
            <DataCard
              className={dataCardClass}
              cardTitle={
                <div className="d-flex flex-items-center gap-1">
                  <span>Secret categories</span>
                  <InfoButton
                    ariaLabel="Secret categories info"
                    title="GitHub scans for many types of secrets: generic secrets, like passwords detected with Copilot, and provider secrets, which come from third-party services through GitHub's partner program — helping keep false positives low."
                  >
                    <InfoButton.Link
                      href={`${helpUrl}/code-security/secret-scanning/copilot-secret-scanning/responsible-ai-generic-secrets`}
                      ariaLabel="Learn about passwords detected with Copilot"
                    >
                      Passwords detected with Copilot
                    </InfoButton.Link>
                    <InfoButton.Link
                      href={`${helpUrl}/code-security/secret-scanning/introduction/about-secret-scanning-for-partners`}
                      ariaLabel="Learn about GitHub's partner program"
                    >
                      GitHub&apos;s partner program
                    </InfoButton.Link>
                  </InfoButton>
                </div>
              }
              loading={assessmentInQueuedState}
            >
              <DataCard.ProgressBar
                data={[
                  {
                    progress:
                      (100 * (assessment.total_tokens_found - assessment.total_tokens_found_non_provider_patterns)) /
                      assessment.total_tokens_found,
                    label: 'Provider patterns',
                  },
                  {
                    progress:
                      (100 * assessment.total_tokens_found_non_provider_patterns) / assessment.total_tokens_found,
                    label: 'Generic patterns',
                  },
                ]}
              />
              <div className="d-flex flex-wrap gap-2 mb-1">
                <ProgressCardItem
                  label="Provider patterns"
                  labelColor="fgColor-accent"
                  data={{
                    count: assessment.total_tokens_found - assessment.total_tokens_found_non_provider_patterns,
                    total: assessment.total_tokens_found,
                  }}
                />
                <ProgressCardItem
                  label="Generic patterns"
                  labelColor="fgColor-success"
                  data={{
                    count: assessment.total_tokens_found_non_provider_patterns,
                    total: assessment.total_tokens_found,
                  }}
                />
              </div>
              <p className="fgColor-muted f6">
                Scan additional secret types with{' '}
                <Link href={`${helpUrl}/code-security/secret-scanning/copilot-secret-scanning`} inline>
                  Copilot AI-detection
                </Link>{' '}
                and{' '}
                <Link
                  href={`${helpUrl}/code-security/secret-scanning/using-advanced-secret-scanning-and-push-protection-features/custom-patterns`}
                  inline
                >
                  custom patterns
                </Link>
                .
              </p>
            </DataCard>
            <DataCard className={dataCardClass} cardTitle="Repositories with leaks" loading={assessmentInQueuedState}>
              <DataCard.Counter
                count={assessment.total_repositories_with_results}
                total={assessment.distinct_repos_scanned}
              />
              <DataCard.Description>
                Repositories where secrets were detected out of all repositories scanned.
              </DataCard.Description>
            </DataCard>
          </>
        )}
      </div>
      <Table.Container>
        {noLeaks ? null : !assessmentInQueuedState ? (
          <>
            <h3 id={dataTableId} className="sr-only">
              Token leaks
            </h3>
            <DataTable aria-labelledby={dataTableId} data={data} columns={columns} />
            <Table.Pagination
              aria-label="Pagination for leaked secrets"
              totalCount={assessment.tokens.length}
              pageSize={pageSize}
              onChange={({pageIndex: newPageIndex}) => setPageIndex(newPageIndex)}
            />
          </>
        ) : (
          <Table.Skeleton aria-label="Token leaks scan in progress" columns={columns.map(x => ({header: x.header}))} />
        )}
      </Table.Container>
    </div>
  )
}
