import {IconButton} from '@primer/react'
import {ArrowLeftIcon} from '@primer/octicons-react'

interface TitleProps {
  text: string
  onBack?: () => void
  backAriaLabel?: string
}

export function Title({text, onBack, backAriaLabel}: TitleProps) {
  if (!onBack) return <>{text}</>

  return (
    <div className="d-flex flex-items-center">
      <IconButton
        aria-label={backAriaLabel ?? 'Back'}
        icon={ArrowLeftIcon}
        variant="invisible"
        size="small"
        onClick={onBack}
        className="mr-1"
      />
      {text}
    </div>
  )
}
