import {useCallback} from 'react'
import {useClickAnalytics} from '@github-ui/use-analytics'

import {
  useEnableGhspMutation,
  useEnableGhspOnSelectedReposMutation,
  useEnableCodeScanningMutation,
  useEnableCodeSecurityOnSelectedReposMutation,
} from '../api'
import {ALL_REPOS_REPO_COUNT, REPO_SELECTION} from '../constants'
import type {EnablementSuccess, RepoSelection} from '../types'

interface UseEnablementMutationsParams {
  orgLogin: string
  assessmentNumber: number
  isSecretProtection: boolean
  repoSelection: RepoSelection
  selectedRepoIds: Set<number>
  handleEnablement: (payload: EnablementSuccess) => void
  handleCloseDialog: () => void
  analyticsCategory: string
}

export function useEnablementMutations({
  orgLogin,
  assessmentNumber,
  isSecretProtection,
  repoSelection,
  selectedRepoIds,
  handleEnablement,
  handleCloseDialog,
  analyticsCategory,
}: UseEnablementMutationsParams) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const enableGhspMutation = useEnableGhspMutation({org: orgLogin, onSettled: handleCloseDialog})
  const enableGhspOnSelectedReposMutation = useEnableGhspOnSelectedReposMutation({
    org: orgLogin,
    assessmentNumber,
    onSettled: handleCloseDialog,
  })
  const enableCodeScanningMutation = useEnableCodeScanningMutation({org: orgLogin})
  const enableCodeSecurityOnSelectedReposMutation = useEnableCodeSecurityOnSelectedReposMutation({org: orgLogin})

  const isMutating =
    enableGhspMutation.isPending ||
    enableGhspOnSelectedReposMutation.isPending ||
    enableCodeScanningMutation.isPending ||
    enableCodeSecurityOnSelectedReposMutation.isPending

  const onEnablementSuccess = useCallback(
    (repoCount: number, data: {show_security_dashboard_button: boolean}) => {
      handleEnablement({
        showBanner: true,
        repoCount,
        showSecurityDashboardButton: data.show_security_dashboard_button,
      })
    },
    [handleEnablement],
  )

  const handleEnableClick = useCallback(() => {
    if (repoSelection === REPO_SELECTION.ALL) {
      if (isSecretProtection) {
        enableGhspMutation.mutate(
          {includePrivateRepos: true},
          {onSuccess: data => onEnablementSuccess(ALL_REPOS_REPO_COUNT, data)},
        )
      } else {
        enableCodeScanningMutation.mutate(undefined, {
          onSuccess: data => onEnablementSuccess(ALL_REPOS_REPO_COUNT, data),
          onSettled: handleCloseDialog,
        })
      }
      sendClickAnalyticsEvent({
        location: 'security-assessment-post-scan',
        category: analyticsCategory,
        action: 'enable-all-repos',
      })
      return
    }

    if (selectedRepoIds.size === 0) return

    const repoIds = Array.from(selectedRepoIds)

    if (isSecretProtection) {
      enableGhspOnSelectedReposMutation.mutate(
        {repoIds},
        {
          onSuccess: data => {
            onEnablementSuccess(typeof data.repo_count === 'number' ? data.repo_count : repoIds.length, data)
          },
        },
      )
    } else {
      enableCodeSecurityOnSelectedReposMutation.mutate(
        {repoIds},
        {
          onSuccess: data => {
            onEnablementSuccess(typeof data.repo_count === 'number' ? data.repo_count : repoIds.length, data)
          },
          onSettled: handleCloseDialog,
        },
      )
    }

    sendClickAnalyticsEvent({
      location: 'security-assessment-post-scan',
      category: analyticsCategory,
      action: 'enable-selected-repos',
      enabledRepoCount: `${selectedRepoIds.size}`,
    })
  }, [
    repoSelection,
    isSecretProtection,
    selectedRepoIds,
    onEnablementSuccess,
    handleCloseDialog,
    analyticsCategory,
    enableGhspMutation,
    enableGhspOnSelectedReposMutation,
    enableCodeScanningMutation,
    enableCodeSecurityOnSelectedReposMutation,
    sendClickAnalyticsEvent,
  ])

  return {
    isMutating,
    handleEnableClick,
  }
}
