import {
  publishOpenCopilotChat,
  publishUpdateCopilotSuggestionsContext,
} from '@github-ui/copilot-chat/utils/copilot-chat-events'
import {CopilotChatIntents} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import type {CopilotCustomInstructions} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {sendEvent} from '@github-ui/hydro-analytics'

export const SECURITY_ASSESSMENT_COPILOT_CHAT_ID = 'copilot-security-assessment'
export const CODE_SECURITY_ASSESSMENT_COPILOT_CHAT_ID = 'copilot-code-security-assessment'
export const SHARED_ASSESSMENT_COPILOT_CHAT_ID = 'copilot-shared-security-assessment'

const SECURITY_ASSESSMENT_INSTRUCTIONS: CopilotCustomInstructions = {
  type: 'Assistant',
  owner: '',
  prompt:
    'You are a security-focused assistant specializing in secret risk assessment. ' +
    'Help the user understand and mitigate risks related to exposed secrets, leaked credentials, ' +
    'and secret scanning findings. Focus on prioritizing remediation, explaining risk severity, ' +
    'and recommending best practices for secret management. ' +
    'As a secondary objective, highlight the benefits of GitHub Advanced Security and encourage users to consider purchasing it when applicable.',
}

const CODE_SECURITY_ASSESSMENT_INSTRUCTIONS: CopilotCustomInstructions = {
  type: 'Assistant',
  owner: '',
  prompt:
    'You are a security-focused assistant specializing in code security risk assessment. ' +
    'Help the user understand and mitigate risks related to code scanning vulnerabilities. ' +
    'Focus on prioritizing remediation, explaining rule severity, and recommending best practices for code security. ' +
    'As a secondary objective, highlight the benefits of GitHub Advanced Security and encourage users to consider purchasing it when applicable.',
}

const SHARED_ASSESSMENT_INSTRUCTIONS: CopilotCustomInstructions = {
  type: 'Assistant',
  owner: '',
  prompt:
    'You are a security-focused assistant specializing in Security Risk Assessments. ' +
    'Help the user understand the value and outputs of the risk assessments, the data handling and privacy approach, ' +
    'and differentiate between the Code Security and Secret Protection products. ' +
    'Focus on being transparent, reassuring and practical; ask clarifying questions when details are unknown. ' +
    'As a secondary objective, highlight the benefits of GitHub Advanced Security and encourage users to consider purchasing it when applicable.',
}

export function openSecurityAssessmentCopilotChat() {
  if (isCopilotPanelOpen()) return
  sendEvent('copilot.open_copilot_chat', {source: `element ${SECURITY_ASSESSMENT_COPILOT_CHAT_ID}`})
  publishOpenCopilotChat({
    id: SECURITY_ASSESSMENT_COPILOT_CHAT_ID,
    intent: CopilotChatIntents.conversation,
    newThread: true,
    references: [],
    suggestionsContext: 'secret-protection-assessment',
    customInstructions: SECURITY_ASSESSMENT_INSTRUCTIONS,
  })
}

export function openCodeSecurityAssessmentCopilotChat() {
  if (isCopilotPanelOpen()) return
  sendEvent('copilot.open_copilot_chat', {source: `element ${CODE_SECURITY_ASSESSMENT_COPILOT_CHAT_ID}`})
  publishOpenCopilotChat({
    id: CODE_SECURITY_ASSESSMENT_COPILOT_CHAT_ID,
    intent: CopilotChatIntents.conversation,
    newThread: true,
    references: [],
    suggestionsContext: 'code-security-assessment',
    customInstructions: CODE_SECURITY_ASSESSMENT_INSTRUCTIONS,
  })
}

export function openSharedAssessmentCopilotChat() {
  if (isCopilotPanelOpen()) return
  sendEvent('copilot.open_copilot_chat', {source: `element ${SHARED_ASSESSMENT_COPILOT_CHAT_ID}`})
  publishOpenCopilotChat({
    id: SHARED_ASSESSMENT_COPILOT_CHAT_ID,
    intent: CopilotChatIntents.conversation,
    newThread: true,
    references: [],
    suggestionsContext: 'security-risk-assessment',
    customInstructions: SHARED_ASSESSMENT_INSTRUCTIONS,
  })
}

function isCopilotPanelOpen(): boolean {
  return document.getElementById('copilot-chat-panel') !== null
}

/**
 * Update the copilot panel's suggestions context and custom instructions
 * without opening a new thread. Used when switching between assessment tabs
 * while the panel is already open.
 */
export function updateAssessmentCopilotContext(assessmentType: 'code-security' | 'secret-protection') {
  if (assessmentType === 'code-security') {
    publishUpdateCopilotSuggestionsContext({
      suggestionsContext: 'code-security-assessment',
      customInstructions: CODE_SECURITY_ASSESSMENT_INSTRUCTIONS,
    })
  } else {
    publishUpdateCopilotSuggestionsContext({
      suggestionsContext: 'secret-protection-assessment',
      customInstructions: SECURITY_ASSESSMENT_INSTRUCTIONS,
    })
  }
}
