import type {ReactNode} from 'react'
import {useState} from 'react'
import {Accordion} from '@github-ui/accordion'
import {Heading} from '@primer/react'
import styles from './Faq.module.css'

export interface FaqItem {
  id: string
  question: string
  answer: ReactNode
}

export function FaqSection({items}: {items: FaqItem[]}) {
  const [expandedItems, setExpandedItems] = useState<string[]>([])

  return (
    <div className="d-flex flex-column gap-3 tmp-px-5 tmp-mt-6">
      <Heading as="h2" variant="medium">
        Frequently asked questions
      </Heading>
      <Accordion expandedItems={expandedItems} onChange={setExpandedItems}>
        {items.map((item, index) => (
          <Accordion.Item key={item.id} value={item.id}>
            <Accordion.Trigger className={index === 0 ? 'pt-0' : undefined}>
              <span className="f4">{item.question}</span>
            </Accordion.Trigger>
            <Accordion.Content className={styles.accordionContent}>{item.answer}</Accordion.Content>
          </Accordion.Item>
        ))}
      </Accordion>
    </div>
  )
}
