import type {ReactNode} from 'react'
import {ActionList, ActionMenu, Button} from '@primer/react'

interface StartTrialActionsProps {
  onStartTrial: () => void
  /**
   * Items rendered inside the enablement overflow menu (typically wrapped in
   * `<ActionList.Item>`s). When null/undefined, the overflow menu is omitted
   * and only the Start trial button is rendered.
   */
  overflowMenuItems?: ReactNode
  startTrialTestId?: string
  overflowMenuTestId?: string
}

/**
 * Banner action set for organizations eligible to start a GHAS trial.
 * Renders a primary "Start trial" button alongside an "Enable" dropdown that
 * exposes the standard enablement entry points.
 */
export function StartTrialActions({
  onStartTrial,
  overflowMenuItems,
  startTrialTestId = 'start-trial-button',
  overflowMenuTestId = 'enablement-overflow-menu',
}: StartTrialActionsProps) {
  return (
    <>
      <Button variant="primary" onClick={onStartTrial} data-testid={startTrialTestId}>
        Start trial
      </Button>
      {overflowMenuItems != null && (
        <ActionMenu>
          <ActionMenu.Button data-testid={overflowMenuTestId}>Enable</ActionMenu.Button>
          <ActionMenu.Overlay width="medium">
            <ActionList>{overflowMenuItems}</ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      )}
    </>
  )
}
