import {type ReactNode, useState} from 'react'
import {clsx} from 'clsx'
import {Button, IconButton, Link, useTheme} from '@primer/react'
import {CopilotIcon, XIcon} from '@primer/octicons-react'

interface RiskAssessmentBannerBaseProps {
  title: ReactNode
  description: ReactNode
  descriptionMaxWidth?: number
  images: {
    day: string
    night: string
  }
  analyticsVisible?: Record<string, string>
  className?: string
  dismissible?: boolean
  autoFocusDismiss?: boolean
}

interface StructuredActionsProps extends RiskAssessmentBannerBaseProps {
  isLoading: boolean
  primaryAction: {
    onClick: () => void
    label: string
  }
  secondaryAction: {
    href: string
    onClick?: () => void
    label: string
  }
  onCopilotAssistClick?: () => void
  actions?: never
}

interface FreeformActionsProps extends RiskAssessmentBannerBaseProps {
  actions?: ReactNode
  isLoading?: never
  primaryAction?: never
  secondaryAction?: never
  onCopilotAssistClick?: never
}

export type RiskAssessmentBannerProps = StructuredActionsProps | FreeformActionsProps

export function RiskAssessmentBanner({
  title,
  description,
  descriptionMaxWidth = 400,
  images,
  analyticsVisible,
  className,
  dismissible = false,
  autoFocusDismiss = false,
  ...rest
}: RiskAssessmentBannerProps) {
  const [isOpen, setIsOpen] = useState(true)
  const {resolvedColorMode} = useTheme()

  if (!isOpen) return null

  return (
    <div
      className={clsx('organization-ipm-banner', dismissible && 'dismissable', className)}
      data-analytics-visible={analyticsVisible ? JSON.stringify(analyticsVisible) : undefined}
    >
      {dismissible && (
        <div className="organization-ipm-banner-dismiss">
          <IconButton
            autoFocus={autoFocusDismiss}
            variant="invisible"
            icon={XIcon}
            aria-label="Dismiss banner"
            onClick={() => setIsOpen(false)}
          />
        </div>
      )}
      <div className="organization-ipm-banner-content">
        <h2 data-hpc className="h4 my-1">
          {title}
        </h2>

        <p className="color-fg-muted mb-0 f5" style={{maxWidth: descriptionMaxWidth}}>
          {description}
        </p>

        <div className="organization-ipm-banner-actions">
          {'actions' in rest && rest.actions != null ? (
            rest.actions
          ) : 'primaryAction' in rest && rest.primaryAction != null ? (
            <>
              <Button
                variant="primary"
                onClick={rest.primaryAction.onClick}
                loading={rest.isLoading}
                className="d-inline-flex flex-items-center gap-1"
              >
                {rest.primaryAction.label}
              </Button>
              {rest.onCopilotAssistClick ? (
                <Button variant="invisible" leadingVisual={CopilotIcon} onClick={rest.onCopilotAssistClick}>
                  Ask Copilot
                </Button>
              ) : (
                <Link href={rest.secondaryAction.href} onClick={rest.secondaryAction.onClick}>
                  {rest.secondaryAction.label}
                </Link>
              )}
            </>
          ) : null}
        </div>
      </div>

      <div className="organization-ipm-banner-image-container">
        <img
          className="organization-ipm-banner-image"
          src={resolvedColorMode === 'night' ? images.night : images.day}
          alt=""
          width={440}
          height={208}
        />
      </div>
    </div>
  )
}
