import Pluralize from 'pluralize'
import {CopilotIcon} from '@primer/octicons-react'
import {UpsellBanner} from '@github-ui/platform-patterns/UpsellBanner'
import {useGhasTrial} from '../../hooks/use-ghas-trial'
import noVulnerabilitiesDay from '../../assets/code-scanning-no-vulnerabilities--day.svg'
import noVulnerabilitiesNight from '../../assets/code-scanning-no-vulnerabilities--night.svg'

export function NoVulnerabilitiesBanner({
  repoCount,
  totalOrgRepos,
  orgLogin,
  onEnableClick,
  onAskCopilotClick,
  onStartTrialClick,
}: {
  repoCount: number
  totalOrgRepos: number
  orgLogin: string
  onEnableClick: () => void
  onAskCopilotClick?: () => void
  onStartTrialClick?: () => void
}) {
  const {canStartTrial} = useGhasTrial()
  const showTrialCta = canStartTrial && onStartTrialClick != null

  const primaryActionText = showTrialCta ? 'Start trial' : 'Enable'
  const primaryActionOnClick = showTrialCta ? onStartTrialClick : onEnableClick

  let secondaryActionText: string | undefined
  let secondaryActionOnClick: (() => void) | undefined
  let secondaryActionIcon: typeof CopilotIcon | undefined
  let secondaryActionHref: string | undefined

  if (showTrialCta) {
    secondaryActionText = 'Enable'
    secondaryActionOnClick = onEnableClick
  } else if (onAskCopilotClick) {
    secondaryActionText = 'Ask Copilot'
    secondaryActionOnClick = onAskCopilotClick
    secondaryActionIcon = CopilotIcon
  } else {
    secondaryActionText = 'Learn more'
    secondaryActionHref = 'https://docs.github.com/code-security/concepts/code-scanning'
  }

  return (
    <UpsellBanner
      heading={`Great work, no vulnerabilities found in the ${Pluralize('repository', repoCount, true)} scanned.`}
      description={`This assessment scanned ${repoCount} of your ${totalOrgRepos} repositories. Enable Code Security to prevent vulnerabilities in your organization.`}
      productShotLight={noVulnerabilitiesDay}
      productShotDark={noVulnerabilitiesNight}
      dismissible
      storageKey={`csra-no-vulnerabilities-dismissed-${orgLogin}`}
      primaryActionText={primaryActionText}
      primaryActionOnClick={primaryActionOnClick}
      secondaryActionText={secondaryActionText}
      secondaryActionOnClick={secondaryActionOnClick}
      secondaryActionIcon={secondaryActionIcon}
      secondaryActionHref={secondaryActionHref}
    />
  )
}
