import {useCallback, useEffect, useMemo, useState} from 'react'
import {debounce} from '@github/mini-throttle'
import type {FilterQuery, SubmitEvent} from '@github-ui/filter-core'
import {useClickAnalytics} from '@github-ui/use-analytics'

interface UseFilterStateParams {
  analyticsCategory: string
}

export function useFilterState({analyticsCategory}: UseFilterStateParams) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const [filterValue, setFilterValue] = useState('')
  const [debouncedFilterValue, setDebouncedFilterValue] = useState('')

  const debouncedSetFilter = useMemo(() => debounce((value: string) => setDebouncedFilterValue(value.trim()), 300), [])

  useEffect(() => {
    return () => debouncedSetFilter.cancel()
  }, [debouncedSetFilter])

  const handleFilterSubmit = useCallback(
    (query: FilterQuery, _eventType: SubmitEvent) => {
      const queryValue = query.raw
      setFilterValue(queryValue)
      setDebouncedFilterValue(queryValue.trim())

      sendClickAnalyticsEvent({
        location: 'security-assessment-post-scan',
        category: analyticsCategory,
        action: 'filter-repos',
      })
    },
    [analyticsCategory, sendClickAnalyticsEvent],
  )

  const handleFilterChange = useCallback(
    (value: string) => {
      setFilterValue(value)
      debouncedSetFilter(value)
    },
    [debouncedSetFilter],
  )

  const resetFilter = useCallback(() => {
    setFilterValue('')
    setDebouncedFilterValue('')
  }, [])

  return {
    filterValue,
    debouncedFilterValue,
    handleFilterSubmit,
    handleFilterChange,
    resetFilter,
  }
}
