import {useState} from 'react'
import {Banner, Dialog, Link, Spinner} from '@primer/react'
import {useQuery} from '@github-ui/react-query'
import Pluralize from 'pluralize'

import {queries, useEnableCodeSecurityOnSelectedReposMutation} from '../../api'
import type {EnablementSuccess, Org} from '../../types'
import {Footer} from '../shared/EnablementDialog/Footer'

interface EnableCodeSecurityRepoDialogProps {
  isOpen: boolean
  onClose: () => void
  org: Org
  repo: {id: number; name: string}
  handleEnablement: (payload: EnablementSuccess) => void
}

export function EnableCodeSecurityRepoDialog({
  isOpen,
  onClose,
  org,
  repo,
  handleEnablement,
}: EnableCodeSecurityRepoDialogProps) {
  const [hasError, setHasError] = useState(false)

  const {
    data: committerData,
    isLoading: isLoadingCommitters,
    isError: isCommitterError,
  } = useQuery({
    ...queries.repoCommitterCount(org.login, repo.id),
    enabled: isOpen,
  })

  const enableMutation = useEnableCodeSecurityOnSelectedReposMutation({org: org.login})

  const handleEnable = () => {
    setHasError(false)
    enableMutation.mutate(
      {repoIds: [repo.id]},
      {
        onSuccess: data => {
          handleEnablement({
            showBanner: true,
            repoCount: 1,
            showSecurityDashboardButton: data.show_security_dashboard_button,
          })
          handleClose()
        },
        onError: () => {
          setHasError(true)
        },
      },
    )
  }

  const handleClose = () => {
    setHasError(false)
    enableMutation.reset()
    onClose()
  }

  const licenseCount = committerData?.committer_count ?? 0

  return isOpen ? (
    <Dialog
      onClose={handleClose}
      title="Enable Code Security"
      width="small"
      renderFooter={() => (
        <Footer
          primaryLabel="Enable"
          primaryAction={handleEnable}
          primaryLoading={enableMutation.isPending}
          primaryDisabled={isLoadingCommitters || isCommitterError}
          onClose={handleClose}
        />
      )}
    >
      {hasError && <Banner variant="critical" title="Failed to enable Code Security. Please try again." />}
      <p>
        Enable Code Security, including code scanning, for <strong>{repo.name}</strong>.
      </p>
      {isLoadingCommitters ? (
        <Spinner size="small" />
      ) : isCommitterError ? (
        <p className="fgColor-danger">Unable to load license information. Close and try again.</p>
      ) : (
        <p>
          <span>
            {licenseCount === 0
              ? 'No additional licenses will be consumed.'
              : `Consume ${licenseCount} additional Code Security ${Pluralize('license', licenseCount)}.`}
          </span>{' '}
          <Link
            inline
            href="https://docs.github.com/en/billing/managing-billing-for-your-products/managing-billing-for-github-advanced-security/about-billing-for-github-advanced-security"
          >
            Learn about Code Security billing.
          </Link>
        </p>
      )}
    </Dialog>
  ) : null
}
