import {useState} from 'react'

import {Banner} from '@primer/react'
import {useQuery} from '@github-ui/react-query'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {useClickAnalytics} from '@github-ui/use-analytics'

import {UpsellBanner} from '@github-ui/platform-patterns/UpsellBanner'

import {queries, useCreateAssessmentMutation} from '../api'
import {CodeSecurityAssessmentResultPage} from '../components/CodeSecurityResultPage'
import {RunAssessmentDialog} from '../components/shared/RunAssessmentDialog'
import sharedStartScanDay from '../assets/shared-start_scan_banner--day.svg'
import sharedStartScanNight from '../assets/shared-start_scan_banner--night.svg'
import type {CreateAssessmentParams, Org} from '../types'
import {DEFAULT_ELIGIBILITY, ASSESSMENT_SOURCE} from '../types'
import {WATCH_A_DEMO_URL} from '../constants'
import {SharedFaq} from '../components/shared/SharedFaq'

const SOURCE = ASSESSMENT_SOURCE.SHARED_LANDING

interface SharedRiskAssessmentPageProps {
  org: Org
  hasExistingAssessment?: boolean
}

export function SharedRiskAssessmentPage({org, hasExistingAssessment}: SharedRiskAssessmentPageProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const mutation = useCreateAssessmentMutation({org: org.login, source: SOURCE})
  const {data: eligibility, isLoading: isEligibilityLoading} = useQuery(queries.eligibility(org.login))
  const resolvedEligibility = eligibility ?? DEFAULT_ELIGIBILITY
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showSraCopilotAssist = useFeatureFlag('risk_assessment_copilot_assistive')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showCsraCopilotAssist = useFeatureFlag('csra_copilot_assistive')
  const showDemoLink = showSraCopilotAssist || showCsraCopilotAssist
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const isBusy = mutation.isPending || isEligibilityLoading

  const handleStartScan = (params: CreateAssessmentParams) => {
    mutation.mutate(params)
  }

  if (hasExistingAssessment) {
    return <CodeSecurityAssessmentResultPage org={org} />
  }

  return (
    <>
      {mutation.isError && (
        <Banner
          variant="critical"
          title="Error"
          description="Failed to scan your organization. Please try again later."
        />
      )}
      <UpsellBanner
        heading="Scan your organization for secrets and vulnerabilities"
        description="Scan your organization for free with Secret Protection and Code Security and view a report with any code vulnerabilities and secrets found."
        primaryActionText="Scan organization"
        primaryActionOnClick={() => {
          if (!isBusy) setIsDialogOpen(true)
        }}
        secondaryActionText={showDemoLink ? 'Watch a demo' : 'Learn more'}
        secondaryActionOnClick={
          showDemoLink
            ? () => {
                sendClickAnalyticsEvent({
                  location: 'security-assessment-pre-scan',
                  category: 'shared-assessment-banner',
                  action: 'watch-demo',
                  tag: 'link',
                  group: 'expand',
                })
              }
            : undefined
        }
        secondaryActionHref={showDemoLink ? WATCH_A_DEMO_URL : '#'}
        productShotLight={sharedStartScanDay}
        productShotDark={sharedStartScanNight}
      />
      <SharedFaq />
      {isDialogOpen && (
        <RunAssessmentDialog
          onClose={() => setIsDialogOpen(false)}
          onStartScan={handleStartScan}
          org={org}
          source={SOURCE}
          eligibility={resolvedEligibility}
        />
      )}
    </>
  )
}
