import {Banner, Dialog, Link} from '@primer/react'
import {orgOnboardingAdvancedSecurityPath} from '@github-ui/paths'
import {ssrSafeWindow} from '@github-ui/ssr-utils'
import {Footer} from './EnablementDialog/Footer'
import {useStartGhasTrialMutation} from '../../api'
import {GHAS_TRIAL_DOCS_URL} from '../../constants'

interface StartTrialDialogProps {
  isOpen: boolean
  onClose: () => void
  orgLogin: string
  /**
   * Number of days included in the trial. Used in the dialog header copy.
   * Falls back to 30 when not provided.
   */
  trialDays?: number
}

export function StartTrialDialog({isOpen, onClose, orgLogin, trialDays = 30}: StartTrialDialogProps) {
  const {mutate, isPending, isError, error, reset} = useStartGhasTrialMutation({org: orgLogin})

  if (!isOpen) return null

  const handleClose = () => {
    reset()
    onClose()
  }

  const handleStart = () => {
    mutate(undefined, {
      onSuccess: () => {
        ssrSafeWindow?.location.assign(orgOnboardingAdvancedSecurityPath({org: orgLogin}))
      },
    })
  }

  return (
    <Dialog
      title={`Start your free ${trialDays} day trial`}
      onClose={handleClose}
      renderFooter={() => (
        <Footer
          primaryLabel="Start trial"
          primaryLoading={isPending}
          primaryDisabled={isPending}
          primaryAction={handleStart}
          onClose={handleClose}
        />
      )}
    >
      <div className="d-flex flex-column gap-3">
        <p className="m-0">
          Your trial includes all Secret Protection and Code Security{' '}
          <Link inline href={GHAS_TRIAL_DOCS_URL} target="_blank" rel="noopener noreferrer">
            features
          </Link>{' '}
          for all organizations and repositories in your enterprise.
        </p>
        <p className="m-0">
          You can convert to a paid plan at any time. If you don&rsquo;t purchase by the end of {trialDays} days, your
          trial will expire and all private repositories will lose access to Secret Protection and Code Security
          features.
        </p>
        <p className="m-0">
          We&rsquo;ll redirect you to the getting started guide in <strong>{orgLogin}</strong>.
        </p>
        {isError && (
          <Banner
            variant="critical"
            title="Failed to start trial"
            description={error?.message || 'Something went wrong starting your trial. Please try again.'}
          />
        )}
      </div>
    </Dialog>
  )
}
