import {useState, useCallback} from 'react'
import type {EnablementSuccess} from '../types'

export function useCodeSecurityEnablementState() {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [repoForDialog, setRepoForDialog] = useState<{id: number; name: string} | null>(null)
  const [enablementBannerPayload, setEnablementBannerPayload] = useState<EnablementSuccess | null>(null)
  const [hasEnabled, setHasEnabled] = useState(false)

  const handleEnablement = useCallback((payload: EnablementSuccess) => {
    setEnablementBannerPayload(payload)
    setHasEnabled(true)
  }, [])

  const dismissEnablement = useCallback(() => {
    setEnablementBannerPayload(null)
    setHasEnabled(false)
  }, [])

  return {
    isDialogOpen,
    setIsDialogOpen,
    repoForDialog,
    setRepoForDialog,
    enablementBannerPayload,
    hasEnabled,
    handleEnablement,
    dismissEnablement,
  }
}
